import{az as a,P as o,Q as l,aQ as n}from"./chunks/framework.oHSDCGnP.js";import"./chunks/theme.SRuXo2Mz.js";const y=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"css/新特性/scope.md","filePath":"css/新特性/scope.md","lastUpdated":1785249401000}'),e={name:"css/新特性/scope.md"};function p(c,s,t,r,i,d){return o(),l("div",null,[...s[0]||(s[0]=[n(`<h2 id="scope-作用域规则" tabindex="-1">@scope 作用域规则 <a class="header-anchor" href="#scope-作用域规则" aria-label="Permalink to “@scope 作用域规则”">​</a></h2><blockquote><p>MDN 参考：<a href="https://developer.mozilla.org/zh-CN/docs/Web/CSS/@scope" target="_blank" rel="noreferrer">https://developer.mozilla.org/zh-CN/docs/Web/CSS/@scope</a></p></blockquote><p><code>@scope</code> 是 CSS 作用域规则，允许把一组样式限定在特定的 DOM 范围内应用，并能显式设置&quot;上界&quot;和&quot;下界&quot;，从机制上解决样式泄漏与覆盖问题。它是组件化样式隔离的官方方案。</p><h3 id="一、为什么需要-scope" tabindex="-1">一、为什么需要 @scope <a class="header-anchor" href="#一、为什么需要-scope" aria-label="Permalink to “一、为什么需要 @scope”">​</a></h3><p>在大型项目或组件库中，常见痛点是：组件内部写的 <code>.title</code> 规则意外泄漏到组件外，或外部全局样式穿透进组件内部覆盖了组件样式。传统手段是靠 BEM 命名、CSS Modules、Shadow DOM 等约束，但都依赖工具或额外约定。</p><p><code>@scope</code> 在 CSS 层面提供了原生的&quot;作用域&quot;概念：限定规则只在指定范围内生效，并可裁剪掉边界外的元素，无需借助类名约定或 Shadow DOM。</p><h3 id="二、-scope-基本语法" tabindex="-1">二、@scope 基本语法 <a class="header-anchor" href="#二、-scope-基本语法" aria-label="Permalink to “二、@scope 基本语法”">​</a></h3><div class="language-css"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#89DDFF;font-style:italic;">@scope</span><span style="color:#BABED8;"> (.media) </span><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">  /* 这些规则只在 .media 内部生效 */</span></span>
<span class="line"><span style="color:#FFCB6B;">  img</span><span style="color:#89DDFF;"> {</span><span style="color:#B2CCD6;"> width</span><span style="color:#89DDFF;">:</span><span style="color:#F78C6C;"> 100%</span><span style="color:#89DDFF;">;</span><span style="color:#89DDFF;"> }</span></span>
<span class="line"><span style="color:#89DDFF;">  .</span><span style="color:#FFCB6B;">title</span><span style="color:#89DDFF;"> {</span><span style="color:#B2CCD6;"> font-size</span><span style="color:#89DDFF;">:</span><span style="color:#F78C6C;"> 1.2rem</span><span style="color:#89DDFF;">;</span><span style="color:#89DDFF;"> }</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span></code></pre></div><p><code>@scope</code> 接受一个选择器作为作用域根（scoping root），其内的规则只匹配该根的后代元素。语法上类似于嵌套，但语义不同：嵌套生成的是组合选择器，<code>@scope</code> 是限定作用域。</p><h3 id="三、作用域限定原理-上界与下界" tabindex="-1">三、作用域限定原理：上界与下界 <a class="header-anchor" href="#三、作用域限定原理-上界与下界" aria-label="Permalink to “三、作用域限定原理：上界与下界”">​</a></h3><p><code>@scope</code> 最强大的地方在于可同时定义<strong>上界（from）</strong>与<strong>下界（to）</strong>，形成&quot;半开区间&quot;的样式作用域：</p><div class="language-css"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#89DDFF;font-style:italic;">@scope</span><span style="color:#BABED8;"> (.media) to (.content) </span><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">  /* 仅作用于 .media 内、但在 .content 之前的元素 */</span></span>
<span class="line"><span style="color:#FFCB6B;">  p</span><span style="color:#89DDFF;"> {</span><span style="color:#B2CCD6;"> color</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> #</span><span style="color:#BABED8;">666</span><span style="color:#89DDFF;">;</span><span style="color:#89DDFF;"> }</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span></code></pre></div><ul><li><code>from</code>：作用域起点（包含）。</li><li><code>to</code>：作用域终点（不包含），常用于排除嵌套的同类组件，避免穿透。</li></ul><p>这种机制天然解决&quot;插槽&quot;或&quot;嵌套组件&quot;的样式隔离问题：内层同名组件不再被外层作用域穿透。</p><h3 id="四、-scope-到特定元素" tabindex="-1">四、@scope 到特定元素 <a class="header-anchor" href="#四、-scope-到特定元素" aria-label="Permalink to “四、@scope 到特定元素”">​</a></h3><p>最简单的用法是把样式绑定到某个组件根：</p><div class="language-css"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#89DDFF;font-style:italic;">@scope</span><span style="color:#BABED8;"> (.card) </span><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#89DDFF;">  .</span><span style="color:#FFCB6B;">title</span><span style="color:#89DDFF;"> {</span><span style="color:#B2CCD6;"> font-weight</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> bold</span><span style="color:#89DDFF;">;</span><span style="color:#89DDFF;"> }</span></span>
<span class="line"><span style="color:#89DDFF;">  .</span><span style="color:#FFCB6B;">body</span><span style="color:#89DDFF;"> {</span><span style="color:#B2CCD6;"> padding</span><span style="color:#89DDFF;">:</span><span style="color:#F78C6C;"> 12px</span><span style="color:#89DDFF;">;</span><span style="color:#89DDFF;"> }</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span></code></pre></div><p>只有 <code>.card</code> 后代中的 <code>.title</code>、<code>.body</code> 会命中，页面其他位置的 <code>.title</code> 不受影响。</p><h3 id="五、-scope-关键字" tabindex="-1">五、:scope 关键字 <a class="header-anchor" href="#五、-scope-关键字" aria-label="Permalink to “五、:scope 关键字”">​</a></h3><p>作用域内可用 <code>:scope</code> 引用作用域根元素本身：</p><div class="language-css"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#89DDFF;font-style:italic;">@scope</span><span style="color:#BABED8;"> (.media) </span><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">  /* 匹配 .media 元素自身 */</span></span>
<span class="line"><span style="color:#89DDFF;">  :</span><span style="color:#C792EA;">scope</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#B2CCD6;">    display</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> flex</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#B2CCD6;">    gap</span><span style="color:#89DDFF;">:</span><span style="color:#F78C6C;"> 12px</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#89DDFF;">  }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;">  /* 匹配 .media 的直接子元素 */</span></span>
<span class="line"><span style="color:#89DDFF;">  :</span><span style="color:#C792EA;">scope</span><span style="color:#89DDFF;"> &gt;</span><span style="color:#FFCB6B;"> *</span><span style="color:#89DDFF;"> {</span><span style="color:#B2CCD6;"> flex</span><span style="color:#89DDFF;">:</span><span style="color:#F78C6C;"> 1</span><span style="color:#89DDFF;">;</span><span style="color:#89DDFF;"> }</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span></code></pre></div><p><code>:scope</code> 让作用域根也能被显式选中并设置样式。</p><h3 id="六、与-css-嵌套对比" tabindex="-1">六、与 CSS 嵌套对比 <a class="header-anchor" href="#六、与-css-嵌套对比" aria-label="Permalink to “六、与 CSS 嵌套对比”">​</a></h3><p><code>@scope</code> 与嵌套（Nesting）都能限定样式范围，但机制不同：</p><table tabindex="0"><thead><tr><th>特性</th><th>CSS 嵌套</th><th>@scope</th></tr></thead><tbody><tr><td>实现方式</td><td>组合选择器（生成 <code>.media img</code>）</td><td>作用域匹配（限定匹配范围）</td></tr><tr><td>边界控制</td><td>无上界/下界概念</td><td>支持上下界（from / to）</td></tr><tr><td>防穿透</td><td>不能阻止嵌套同类组件被穿透</td><td><code>to</code> 可裁剪下界</td></tr><tr><td>选择器特异性</td><td>由生成的组合选择器决定</td><td>不增加额外特异性</td></tr></tbody></table><div class="language-css"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#676E95;font-style:italic;">/* 嵌套：.card .title */</span></span>
<span class="line"><span style="color:#89DDFF;">.</span><span style="color:#FFCB6B;">card</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#BABED8;">  .title { </span><span style="color:#B2CCD6;">color</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> red</span><span style="color:#89DDFF;">;</span><span style="color:#89DDFF;"> }</span></span>
<span class="line"><span style="color:#BABED8;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;">/* @scope：仅 .card 内的 .title */</span></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">@scope</span><span style="color:#BABED8;"> (.card) </span><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#89DDFF;">  .</span><span style="color:#FFCB6B;">title</span><span style="color:#89DDFF;"> {</span><span style="color:#B2CCD6;"> color</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> red</span><span style="color:#89DDFF;">;</span><span style="color:#89DDFF;"> }</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span></code></pre></div><p>嵌套没有&quot;下界&quot;，若 <code>.card</code> 内嵌套了另一个 <code>.card</code>，内层的 <code>.title</code> 也会被外层命中。<code>@scope</code> 用 <code>to</code> 可以阻断这种穿透。</p><h3 id="七、解决样式泄漏问题" tabindex="-1">七、解决样式泄漏问题 <a class="header-anchor" href="#七、解决样式泄漏问题" aria-label="Permalink to “七、解决样式泄漏问题”">​</a></h3><p><code>@scope</code> 天然适合组件样式隔离，避免互相污染：</p><div class="language-css"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#676E95;font-style:italic;">/* 仅作用于对话框组件，不影响页面上其他 .title */</span></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">@scope</span><span style="color:#BABED8;"> (.dialog) to (.dialog) </span><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#89DDFF;">  .</span><span style="color:#FFCB6B;">title</span><span style="color:#89DDFF;"> {</span><span style="color:#B2CCD6;"> font-size</span><span style="color:#89DDFF;">:</span><span style="color:#F78C6C;"> 1.5rem</span><span style="color:#89DDFF;">;</span><span style="color:#89DDFF;"> }</span></span>
<span class="line"><span style="color:#89DDFF;">  .</span><span style="color:#FFCB6B;">close</span><span style="color:#89DDFF;"> {</span><span style="color:#B2CCD6;"> position</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> absolute</span><span style="color:#89DDFF;">;</span><span style="color:#B2CCD6;"> top</span><span style="color:#89DDFF;">:</span><span style="color:#F78C6C;"> 8px</span><span style="color:#89DDFF;">;</span><span style="color:#B2CCD6;"> right</span><span style="color:#89DDFF;">:</span><span style="color:#F78C6C;"> 8px</span><span style="color:#89DDFF;">;</span><span style="color:#89DDFF;"> }</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span></code></pre></div><p><code>to (.dialog)</code> 的含义是：作用域到内部第一个 <code>.dialog</code> 为止，不再向下穿透。这样嵌套对话框的样式相互独立。</p><h3 id="八、实际应用场景" tabindex="-1">八、实际应用场景 <a class="header-anchor" href="#八、实际应用场景" aria-label="Permalink to “八、实际应用场景”">​</a></h3><h4 id="_1-组件库样式隔离" tabindex="-1">1. 组件库样式隔离 <a class="header-anchor" href="#_1-组件库样式隔离" aria-label="Permalink to “1. 组件库样式隔离”">​</a></h4><p>第三方组件库希望样式只在自身根节点内生效，不污染宿主页面：</p><div class="language-css"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#89DDFF;font-style:italic;">@scope</span><span style="color:#BABED8;"> (.my-component) </span><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#FFCB6B;">  h1</span><span style="color:#89DDFF;">,</span><span style="color:#FFCB6B;"> h2</span><span style="color:#89DDFF;">,</span><span style="color:#FFCB6B;"> p</span><span style="color:#89DDFF;"> {</span><span style="color:#B2CCD6;"> margin</span><span style="color:#89DDFF;">:</span><span style="color:#F78C6C;"> 0</span><span style="color:#89DDFF;">;</span><span style="color:#89DDFF;"> }</span></span>
<span class="line"><span style="color:#FFCB6B;">  button</span><span style="color:#89DDFF;"> {</span><span style="color:#B2CCD6;"> cursor</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> pointer</span><span style="color:#89DDFF;">;</span><span style="color:#89DDFF;"> }</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span></code></pre></div><h4 id="_2-根据内容主题切换" tabindex="-1">2. 根据内容主题切换 <a class="header-anchor" href="#_2-根据内容主题切换" aria-label="Permalink to “2. 根据内容主题切换”">​</a></h4><div class="language-css"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#89DDFF;font-style:italic;">@scope</span><span style="color:#BABED8;"> (.dark-theme) </span><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#BABED8;">  background: </span><span style="color:#89DDFF;">#</span><span style="color:#BABED8;">1f2937;</span></span>
<span class="line"><span style="color:#BABED8;">  color: </span><span style="color:#89DDFF;">#</span><span style="color:#BABED8;">f9fafb;</span></span>
<span class="line"><span style="color:#BABED8;">}</span></span></code></pre></div><p>只切换某一块区域的主题，而非全局。</p><h3 id="九、浏览器兼容性" tabindex="-1">九、浏览器兼容性 <a class="header-anchor" href="#九、浏览器兼容性" aria-label="Permalink to “九、浏览器兼容性”">​</a></h3><p><code>@scope</code> 是较新的特性，兼容性正在铺开：</p><ul><li>Chrome / Edge：118+（2023 年 10 月）</li><li>Safari：17.4+（2024 年 1 月）</li><li>Firefox：暂未稳定支持（实验中）</li></ul><p>由于兼容性仍在完善，生产环境使用建议配合特性检测 <code>@supports at-rule(@scope)</code> 做回退，或暂时与 CSS Modules / Shadow DOM 方案并存。</p>`,42)])])}const h=a(e,[["render",p]]);export{y as __pageData,h as default};
